(()=>{const root=document.querySelector('.mh09');if(!root)return;const group=root.querySelector('.mh09-filters'),cards=[...root.querySelectorAll('[data-method-tags]')],buttons=[...root.querySelectorAll('[data-method-filter]')],count=root.querySelector('#mh09-count');if(!group||!cards.length)return;group.hidden=false;buttons.forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.methodFilter;let visible=0;cards.forEach(card=>{const show=key==='all'||card.dataset.methodTags.split(' ').includes(key);card.hidden=!show;if(show)visible++});buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));count.textContent=visible+' hizmet başlığı gösteriliyor.'}));})();